CREATE INDEX "task_runs_sleep_check_finished_completed_idx" ON "task_runs" USING btree ("completed_at") WHERE "task_runs"."status" IN ('failed', 'canceled', 'completed') AND "task_runs"."machine_id" IS NOT NULL AND "task_runs"."sleep_requested_at" IS NULL AND "task_runs"."snapshot_id" IS NULL AND "task_runs"."snapshot_requested_at" IS NULL AND "task_runs"."vendor" IN ('modal', 'daytona', 'e2b', 'docker', 'blaxel', 'box', 'roomote', 'azure') AND "task_runs"."completed_at" IS NOT NULL;--> statement-breakpoint
CREATE INDEX "task_runs_sleep_check_finished_canceled_idx" ON "task_runs" USING btree ("canceled_at") WHERE "task_runs"."status" IN ('failed', 'canceled', 'completed') AND "task_runs"."machine_id" IS NOT NULL AND "task_runs"."sleep_requested_at" IS NULL AND "task_runs"."snapshot_id" IS NULL AND "task_runs"."snapshot_requested_at" IS NULL AND "task_runs"."vendor" IN ('modal', 'daytona', 'e2b', 'docker', 'blaxel', 'box', 'roomote', 'azure') AND "task_runs"."completed_at" IS NULL AND "task_runs"."canceled_at" IS NOT NULL;